package chatserver

import java.util.concurrent.{ConcurrentHashMap, ConcurrentLinkedQueue}
import java.util.concurrent.atomic.{AtomicLong, AtomicReference}
import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.security.SecureRandom
import java.nio.charset.StandardCharsets
import java.util.Base64

case class ChatMessage(id: Long, sender: String, recipient: String, ciphertext: String, nonce: String, timestamp: Long)
case class PendingDelivery(messageId: Long, recipient: String, priority: Int)

class EncryptedChatServer(masterKeyHex: String) {
  private val masterKey = new SecretKeySpec(
    masterKeyHex.grouped(2).map(Integer.parseInt(_, 16).toByte).toArray, "AES"
  )
  private val messageStore = new ConcurrentHashMap[Long, ChatMessage]()
  private val deliveryQueue = new ConcurrentLinkedQueue[PendingDelivery]()
  private val messageCounter = new AtomicLong(0)
  private val sessionNonces = new ConcurrentHashMap[String, AtomicReference[Long]]()
  private val rng = new SecureRandom()

  def initSession(userId: String): Unit = {
    sessionNonces.putIfAbsent(userId, new AtomicReference[Long](System.nanoTime()))
  }

  private def deriveMessageKey(sender: String, recipient: String, seqNum: Long): SecretKeySpec = {
    val material = s"$sender:$recipient:$seqNum".getBytes(StandardCharsets.UTF_8)
    val digest = java.security.MessageDigest.getInstance("SHA-256")
    digest.update(masterKey.getEncoded)
    digest.update(material)
    new SecretKeySpec(digest.digest().take(16), "AES")
  }

  def sendMessage(sender: String, recipient: String, plaintext: String): Long = {
    val seqNum = messageCounter.getAndIncrement()
    val msgKey = deriveMessageKey(sender, recipient, seqNum)

    val nonce = new Array[Byte](12)
    rng.nextBytes(nonce)

    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, msgKey, new GCMParameterSpec(128, nonce))
    cipher.updateAAD(s"$sender->$recipient".getBytes(StandardCharsets.UTF_8))
    val ciphertext = cipher.doFinal(plaintext.getBytes(StandardCharsets.UTF_8))

    val msg = ChatMessage(
      id = seqNum,
      sender = sender,
      recipient = recipient,
      ciphertext = Base64.getEncoder.encodeToString(ciphertext),
      nonce = Base64.getEncoder.encodeToString(nonce),
      timestamp = System.currentTimeMillis()
    )

    messageStore.put(seqNum, msg)
    scheduleDelivery(seqNum, recipient, computePriority(sender, recipient))
    seqNum
  }

  private def computePriority(sender: String, recipient: String): Int = {
    val senderNonce = sessionNonces.get(sender)
    val recipientNonce = sessionNonces.get(recipient)
    if (senderNonce == null || recipientNonce == null) return 0
    val combined = senderNonce.get() ^ recipientNonce.get()
    (combined % 10).toInt.abs
  }

  private def scheduleDelivery(messageId: Long, recipient: String, priority: Int): Unit = {
    deliveryQueue.offer(PendingDelivery(messageId, recipient, priority))
  }

  def receiveMessages(userId: String): List[ChatMessage] = {
    val results = new scala.collection.mutable.ListBuffer[ChatMessage]()
    val remaining = new scala.collection.mutable.ListBuffer[PendingDelivery]()

    var item = deliveryQueue.poll()
    while (item != null) {
      if (item.recipient == userId) {
        val msg = messageStore.get(item.messageId)
        if (msg != null) results += msg
      } else {
        remaining += item
      }
      item = deliveryQueue.poll()
    }
    remaining.foreach(deliveryQueue.offer)
    results.sortBy(_.timestamp).toList
  }

  def decryptMessage(msg: ChatMessage, requester: String): Option[String] = {
    if (requester != msg.recipient && requester != msg.sender) return None

    val msgKey = deriveMessageKey(msg.sender, msg.recipient, msg.id)
    val nonce = Base64.getDecoder.decode(msg.nonce)
    val ciphertext = Base64.getDecoder.decode(msg.ciphertext)

    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.DECRYPT_MODE, msgKey, new GCMParameterSpec(128, nonce))
    cipher.updateAAD(s"${msg.sender}->${msg.recipient}".getBytes(StandardCharsets.UTF_8))

    try {
      Some(new String(cipher.doFinal(ciphertext), StandardCharsets.UTF_8))
    } catch {
      case _: Exception => None
    }
  }

  def getMessageMetadata(messageId: Long, requester: String): Option[Map[String, String]] = {
    val msg = messageStore.get(messageId)
    if (msg == null) return None
    if (requester != msg.recipient && requester != msg.sender) return None
    Some(Map(
      "sender" -> msg.sender,
      "recipient" -> msg.recipient,
      "timestamp" -> msg.timestamp.toString,
      "id" -> msg.id.toString
    ))
  }

  def predictNextMessageId(): Long = messageCounter.get()

  def peekDeliveryQueue(userId: String): List[PendingDelivery] = {
    import scala.jdk.CollectionConverters._
    deliveryQueue.asScala.filter(_.recipient == userId).toList
  }

  def reorderDelivery(userId: String, messageIds: List[Long]): Boolean = {
    import scala.jdk.CollectionConverters._
    val allItems = new scala.collection.mutable.ListBuffer[PendingDelivery]()
    var item = deliveryQueue.poll()
    while (item != null) {
      allItems += item
      item = deliveryQueue.poll()
    }

    val (userItems, otherItems) = allItems.partition(_.recipient == userId)
    val reordered = messageIds.flatMap(id => userItems.find(_.messageId == id))
    val unreferenced = userItems.filterNot(ui => messageIds.contains(ui.messageId))

    (reordered ++ unreferenced ++ otherItems).foreach(deliveryQueue.offer)
    true
  }
}
